behavioralTests:
const itemsOf = () => Array.from(container.querySelectorAll('[data-test="item"]')).map(n => n.textContent.trim());
let items = itemsOf();
expect(items.length === 3, 'page 0 should have 3 items, got ' + items.length);
expect(items[0] === 'alpha' && items[2] === 'charlie', 'page 0 items: ' + JSON.stringify(items));
container.querySelector('[data-test="next"]').click();
await tick();
items = itemsOf();
expect(items[0] === 'delta' && items[2] === 'foxtrot', 'page 1 items: ' + JSON.stringify(items));
container.querySelector('[data-test="prev"]').click();
await tick();
items = itemsOf();
expect(items[0] === 'alpha', 'back to page 0: ' + JSON.stringify(items));
container.querySelector('[data-test="prev"]').click();
await tick();
items = itemsOf();
expect(items[0] === 'alpha', 'prev clamps at 0: ' + JSON.stringify(items));
